/* Demonstrates reading an integer and a string from a file using fscanf() and checking return values. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define FILENAME "test_input.txt"

int main() {
    FILE *fp = NULL;
    int age;
    char name[50];
    int expected_items = 2;

    // 1. Setup: Write dummy data to the file (e.g., '30 Alice')
    if ((fp = fopen(FILENAME, "w")) == NULL) {
        perror("Error creating file");
        return EXIT_FAILURE;
    }
    fprintf(fp, "30 Alice\n");
    fclose(fp);

    // 2. Open file for reading
    if ((fp = fopen(FILENAME, "r")) == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    // 3. Use fscanf to read formatted data
    printf("Attempting to read data from %s...\n", FILENAME);
    int count = fscanf(fp, "%d %49s", &age, name);

    // 4. Handle results based on return value
    if (count == expected_items) {
        printf("Success! Read %d items:\n", count);
        printf("  Age: %d\n", age);
        printf("  Name: %s\n", name);
    } else if (count == EOF) {
        if (ferror(fp)) {
            perror("Read error occurred");
            fclose(fp);
            return EXIT_FAILURE;
        }
        printf("End of file reached before conversion started.\n");
    } else {
        // Conversion failure or incomplete match
        printf("Error: Expected %d items, but only read %d items.\n", expected_items, count);
    }

    fclose(fp);
    return EXIT_SUCCESS;
}
